{
  "schema_version": "ruler_chapter_judgment_v1",
  "job_key": "chapter-judge:2022-putin-full-bias-v2:2022:8B",
  "run_key": "2022-putin-full-bias-v2",
  "chapter_id": "8B",
  "target_year": 2022,
  "rubric_version": "chapter_8b_v3",
  "calibration_batch_id": "chapter-judge:2022-putin-full-bias-v2:2022:8B",
  "evaluations": [
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BGD:17068",
      "iso3": "BGD",
      "ruler_id": "2992",
      "ruler_year_id": 17068,
      "ruler_name": "Sheikh Hasina",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "8B",
      "rubric_version": "chapter_8b_v3",
      "calibration_batch_id": "chapter-judge:2022-putin-full-bias-v2:2022:8B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810",
        "dossier:2022-top20-hybrid-v2:2022:CHN:15832"
      ],
      "score_1_to_10": 6.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 78,
      "plausible_score_range": {
        "lower": 6.0,
        "upper": 7.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E094",
          "explanation": "A PM-chaired governing body was established to implement the Delta Plan 2100, showing concrete institutional control rather than slogan-only ambition."
        },
        {
          "evidence_id": "E095",
          "explanation": "The Power Division's ERP rollout and award show real administrative implementation across subordinate bodies."
        },
        {
          "evidence_id": "E098",
          "explanation": "The IMF staff-level agreement shows the authorities moving into a live macro-stabilization program under Hasina's government."
        },
        {
          "evidence_id": "E100",
          "explanation": "World Bank data on falling extreme poverty and improved services supports meaningful though lagged outcome progress."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E097",
          "explanation": "The IMF also notes unresolved vulnerabilities and the need for further investment, which caps claims of strong overall competence."
        },
        {
          "evidence_id": "E098",
          "explanation": "The same IMF agreement was crisis response after reserve stress, so it is not clean evidence of prior policy success."
        },
        {
          "evidence_id": "E100",
          "explanation": "The gains are retrospective and long-run, so they are only partially attributable to 2022 decision-making."
        }
      ],
      "inherited_baseline_and_constraints": "Bangladesh entered 2022 with strong growth momentum but macro stress, reserve pressure, and pandemic aftereffects. I credited Hasina for real implementation capacity while treating long-run development gains, external demand, and crisis response as shared causes rather than personal mastery.",
      "ruler_attribution": "Substantial but not exclusive. The record shows government-level implementation under Hasina with PM-chaired machinery and visible delivery, but many gains are institutional or retrospective rather than personally micromanaged.",
      "supported_lenses": [
        "8B.1",
        "8B.2",
        "8B.3",
        "8B.4",
        "8B.5",
        "8B.6",
        "8B.7",
        "8B.8",
        "8B.9",
        "8B.10"
      ],
      "missing_or_weak_lenses": [
        "8B.4",
        "8B.7",
        "8B.8",
        "8B.10"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E097",
          "explanation": "Macro vulnerabilities and the need for more investment weaken any claim of exceptional performance."
        },
        {
          "evidence_id": "E100",
          "explanation": "Outcome gains are real but lagged and not uniquely 2022-owned."
        }
      ],
      "source_mix": "Official government, IMF, World Bank, UNICEF, and contemporaneous media. The dossier is strong on formal implementation and outcomes, but several positive items are self-descriptions that I discounted unless independently echoed.",
      "structured_prior_summary": "The priors point to middling-to-weak governance quality on accountability and rule of law, with relatively weak WGI government effectiveness and regulatory quality. I treated those as background constraints, not as score inputs.",
      "bias_assessment": {
        "material_biases": [
          {
            "bias": "Official and retrospective development sources can overstate continuity and understate bottlenecks.",
            "supporting_evidence_ids": [
              "E094",
              "E095",
              "E098",
              "E100"
            ],
            "likely_direction": "favors_ruler",
            "interpretation_effect": "I credited real implementation but kept the score below the high anchor because several gains are institutional or retrospective rather than independently audited in-year."
          },
          {
            "bias": "The dossier is richer on macro and program architecture than on project-level delivery audits.",
            "supporting_evidence_ids": [
              "E093",
              "E097",
              "E098",
              "E100"
            ],
            "likely_direction": "uncertain",
            "interpretation_effect": "This widens the plausible range because some competence is demonstrated by structure and follow-through, but not all outcome claims can be cleanly attributed."
          }
        ],
        "confidence_and_range_effect": "Confidence is moderate-high because the record includes direct institutional action plus outcome data, but the score range remains wider than a pure legal-text case because attribution is partly indirect and several achievements are retrospective.",
        "remaining_uncertainty": "The biggest uncertainty is how much of the development and macro performance is due to Hasina's 2022 choices versus inherited growth, external demand, and earlier reforms.",
        "report_volume_not_used_as_severity": true,
        "no_blanket_regime_correction": true
      },
      "chapter_rationale": "Hasina scores moderately high on competence because the dossier shows a real governing program that was converted into institutions, operating mechanisms, and observable results. The Delta Plan was backed by a PM-chaired council; procurement, power-sector digitalization, education response, and macro stabilization all show more than symbolic direction. The strongest favorable evidence is not just rhetoric but implementation and some outcome improvement, including poverty reduction and faster, more transparent procurement. The limiting facts are that several achievements are institutional or retrospective, macro stress remained serious, and some claims are better read as state-level or ministry-level execution than personal micromanagement. I therefore place this above a merely mixed score but below a genuinely high score. Moral approval of the program did not affect the assessment.",
      "lower_anchor_rejected": "A lower score would ignore the tangible implementation record: the PM-chaired Delta governance machinery, concrete ERP and policy execution, and measurable development gains are too substantial for a merely average or weak competence judgment.",
      "higher_anchor_rejected": "A higher score is not warranted because key gains are partly inherited, indirect, or retrospective, and the dossier still records macro vulnerability and incomplete causal attribution for several of the best outcomes.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "program_basis",
          "value": "mostly_explicit"
        },
        {
          "field": "program_type",
          "value": "policy; state_building; regime_control"
        },
        {
          "field": "strategic_clarity",
          "value": "clear"
        },
        {
          "field": "operationalization",
          "value": "strong"
        },
        {
          "field": "mobilization_and_coordination",
          "value": "strong"
        },
        {
          "field": "adaptation",
          "value": "effective"
        },
        {
          "field": "goal_progress",
          "value": "substantial"
        },
        {
          "field": "durability",
          "value": "durable"
        },
        {
          "field": "morality_separation_check",
          "value": "Moral approval or disapproval of the government did not affect the competence score."
        },
        {
          "field": "trajectory",
          "value": "steady improvement with some macro stress and incomplete outcome attribution"
        },
        {
          "field": "lens_strengths",
          "value": "8B.2, 8B.3, 8B.5, 8B.6, 8B.7, 8B.9, 8B.10"
        },
        {
          "field": "lens_gaps",
          "value": "Direct ruler micromanagement and independently audited project-level outcomes are thinner than the institutional record."
        },
        {
          "field": "defensible_score_range",
          "value": "6.0-7.5"
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
      "iso3": "BRA",
      "ruler_id": "3413",
      "ruler_year_id": 19646,
      "ruler_name": "Jair Bolsonaro",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "8B",
      "rubric_version": "chapter_8b_v3",
      "calibration_batch_id": "chapter-judge:2022-putin-full-bias-v2:2022:8B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810",
        "dossier:2022-top20-hybrid-v2:2022:CHN:15832"
      ],
      "score_1_to_10": 4.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 82,
      "plausible_score_range": {
        "lower": 3.5,
        "upper": 4.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E085",
          "explanation": "Bolsonaro exerted direct pressure on Petrobras, showing real personal leverage over a core state asset."
        },
        {
          "evidence_id": "E086",
          "explanation": "His government actually ousted the Petrobras chief and altered fuel-price policy, which is concrete though politicized execution."
        },
        {
          "evidence_id": "E093",
          "explanation": "The election-year package shows the state machine was used for tactical mobilization, not just rhetoric."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E082",
          "explanation": "The fact-check compilation of repeated distortions undermines claims of disciplined or reliable program execution."
        },
        {
          "evidence_id": "E092",
          "explanation": "The campaign plan is a promise document, not proof of delivery, so it cannot carry the score upward much."
        },
        {
          "evidence_id": "E084",
          "explanation": "The TSE investigation shows institutional scrutiny of Bolsonaro's conduct in office and during the campaign."
        }
      ],
      "inherited_baseline_and_constraints": "Brazil had institutional checks and a competitive electoral environment, but Bolsonaro's 2022 record was shaped by tactical power retention, budget stress, and a lot of performative rather than programmatic action. I credited the real use of executive power without confusing that with broad governing effectiveness.",
      "ruler_attribution": "Direct for personnel pressure and election-year mobilization, but the record is weak on durable program execution and strong on tactical, contested, or self-serving choices.",
      "supported_lenses": [
        "8B.1",
        "8B.2",
        "8B.3",
        "8B.4",
        "8B.5",
        "8B.6",
        "8B.7",
        "8B.8",
        "8B.9",
        "8B.10"
      ],
      "missing_or_weak_lenses": [
        "8B.6",
        "8B.7",
        "8B.8",
        "8B.10"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E082",
          "explanation": "The record is thick on false or distorted statements, which is bad for effectiveness because it weakens planning credibility and coordination."
        },
        {
          "evidence_id": "E092",
          "explanation": "The campaign platform is real program articulation, but it remains largely unexecuted in the dossier."
        }
      ],
      "source_mix": "Mostly Reuters, official election/judicial records, and campaign material. The dossier is good for tactical moves and official pressure, but much weaker for durable, audited policy execution.",
      "structured_prior_summary": "The priors are not especially weak institutionally, which makes the low score more about Bolsonaro's 2022 performance than about Brazilian state capacity as such.",
      "bias_assessment": {
        "material_biases": [
          {
            "bias": "Fact-check compilations and election-year press coverage overweight visible rhetoric and tactical conflict.",
            "supporting_evidence_ids": [
              "E082",
              "E084",
              "E093"
            ],
            "likely_direction": "favors_ruler",
            "interpretation_effect": "I did not treat the volume of criticism as severity by itself, but the pattern still lowered confidence in the coherence of Bolsonaro's governing program."
          },
          {
            "bias": "The dossier has more evidence of tactical pressure than of durable program delivery.",
            "supporting_evidence_ids": [
              "E085",
              "E086",
              "E087",
              "E093"
            ],
            "likely_direction": "mixed",
            "interpretation_effect": "This keeps the score in the low-middle band rather than a true collapse score, because he still used state power effectively for some short-term objectives."
          }
        ],
        "confidence_and_range_effect": "Confidence is fairly high because the evidence is direct and time-locked, but the score stays low because the record is mostly tactical power use rather than durable administration.",
        "remaining_uncertainty": "The main uncertainty is how much to credit politicized state use as competence rather than as an indicator of narrow, self-protective control.",
        "report_volume_not_used_as_severity": true,
        "no_blanket_regime_correction": true
      },
      "chapter_rationale": "Bolsonaro scores low on effectiveness because the dossier shows a president who could still use office power, but mostly for tactical pressure, coalition maneuvering, and election-year mobilization rather than durable governing competence. He pressed Petrobras, used the state machine around the campaign, and maintained some executive leverage. But the core record is dominated by repeated distortions, institutional scrutiny, and a policy portfolio that is more proclaimed than executed. The 2022 material does not show broad, sustained conversion of his stated program into effective state action. Moral judgment is not what drives the score; the issue is that his most visible choices did not translate into coherent, durable administrative progress.",
      "lower_anchor_rejected": "A lower score would ignore the fact that Bolsonaro did achieve some concrete tactical control over personnel and policy levers, especially around Petrobras and the election-year state response.",
      "higher_anchor_rejected": "A higher score is not justified because the dossier lacks durable, independently verified program execution and instead shows a pattern of rhetorical inflation, contestation, and tactical rather than administrative use of power.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "program_basis",
          "value": "mostly_explicit"
        },
        {
          "field": "program_type",
          "value": "power_consolidation; policy; regime_control"
        },
        {
          "field": "strategic_clarity",
          "value": "partial"
        },
        {
          "field": "operationalization",
          "value": "mixed"
        },
        {
          "field": "mobilization_and_coordination",
          "value": "mixed"
        },
        {
          "field": "adaptation",
          "value": "rigid"
        },
        {
          "field": "goal_progress",
          "value": "mixed"
        },
        {
          "field": "durability",
          "value": "fragile"
        },
        {
          "field": "morality_separation_check",
          "value": "Moral disapproval of the rhetoric or campaign tactics did not itself determine the score."
        },
        {
          "field": "trajectory",
          "value": "short-term tactical gains, weak durable administration"
        },
        {
          "field": "lens_strengths",
          "value": "8B.2, 8B.3, 8B.5, 8B.6, 8B.9"
        },
        {
          "field": "lens_gaps",
          "value": "Very thin durable-outcome evidence and weak support for broad policy execution."
        },
        {
          "field": "defensible_score_range",
          "value": "3.5-4.5"
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:CHN:15832",
      "iso3": "CHN",
      "ruler_id": "1432",
      "ruler_year_id": 15832,
      "ruler_name": "Xi Jinping",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "8B",
      "rubric_version": "chapter_8b_v3",
      "calibration_batch_id": "chapter-judge:2022-putin-full-bias-v2:2022:8B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
        "dossier:2022-top20-hybrid-v2:2022:USA:15810",
        "dossier:2022-top20-hybrid-v2:2022:CHN:15832"
      ],
      "score_1_to_10": 7.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 84,
      "plausible_score_range": {
        "lower": 7.0,
        "upper": 8.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E076",
          "explanation": "Xi secured a precedent-breaking third term and stacked the leadership with loyalists, showing strong elite control and strategic continuity."
        },
        {
          "evidence_id": "E087",
          "explanation": "The congress formally centered Xi and adopted his report and program, indicating effective conversion of authority into party-state action."
        },
        {
          "evidence_id": "E089",
          "explanation": "The central policy package was translated into implementation instructions to keep the economy stable."
        },
        {
          "evidence_id": "E090",
          "explanation": "Special inspections in 12 provinces and corrective follow-up show administrative enforcement rather than mere announcement."
        },
        {
          "evidence_id": "E096",
          "explanation": "R&D spending and intensity rose, consistent with sustained industrial and innovation priorities under Xi's system."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E093",
          "explanation": "The late-year COVID policy reversal after protests shows the system could adapt, but also that the earlier posture had become costly and reactive."
        },
        {
          "evidence_id": "E092",
          "explanation": "Property-sector rescue was corrective rather than preventive, which caps the score below the highest anchor."
        },
        {
          "evidence_id": "E096",
          "explanation": "Higher R&D inputs do not by themselves prove efficient conversion into output or broad productivity gains."
        }
      ],
      "inherited_baseline_and_constraints": "Xi inherited a powerful party-state with major control capacity, and in 2022 he used it effectively to consolidate elite loyalty, push policy packages, and correct course when necessary. I discounted inherited centralization as such and asked whether his own program advanced; the evidence says yes, substantially, though not flawlessly.",
      "ruler_attribution": "Strong. The major leadership reshuffle, program framing, economic dispatch, and policy correction all sit squarely within Xi's authority, even when implementation occurred through the State Council and regulators.",
      "supported_lenses": [
        "8B.1",
        "8B.2",
        "8B.3",
        "8B.4",
        "8B.5",
        "8B.6",
        "8B.7",
        "8B.8",
        "8B.9",
        "8B.10"
      ],
      "missing_or_weak_lenses": [
        "8B.7",
        "8B.8"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E093",
          "explanation": "The zero-COVID reversal was a real correction but also a sign of policy strain and resistance."
        },
        {
          "evidence_id": "E092",
          "explanation": "The property rescue shows the state reacting to a serious problem rather than preventing it cleanly."
        }
      ],
      "source_mix": "Official congress records, government notices, Reuters reporting, specialist analysis, and statistics. The dossier is heavily system-level but still includes clear ruler-linked choices and corrections.",
      "structured_prior_summary": "The priors are consistent with a high-capacity authoritarian state: weak accountability, moderate rule of law, and strong government effectiveness. Those priors support a high ceiling but do not by themselves determine the score.",
      "bias_assessment": {
        "material_biases": [
          {
            "bias": "Official party-state sources can overstate coherence and understate implementation problems.",
            "supporting_evidence_ids": [
              "E087",
              "E089",
              "E090",
              "E096"
            ],
            "likely_direction": "favors_ruler",
            "interpretation_effect": "I accepted the program and elite-control evidence but kept the score below the highest anchor because the dossier still shows reactive correction and sectoral stress."
          },
          {
            "bias": "Analytical reporting on elite control can over-read loyalty as competence.",
            "supporting_evidence_ids": [
              "E075",
              "E076",
              "E083",
              "E084"
            ],
            "likely_direction": "favors_ruler",
            "interpretation_effect": "I treated loyalist stacking as competence only insofar as it advanced Xi's stated program, not as proof of broader economic or social success."
          }
        ],
        "confidence_and_range_effect": "Confidence is high because the record is direct on leadership control and policy dispatch, but the score range remains open because outcome conversion is not equally strong across all priorities.",
        "remaining_uncertainty": "The biggest open question is how much durable economic or social progress actually followed from the high-control political settlement, especially once the property and COVID strains are accounted for.",
        "report_volume_not_used_as_severity": true,
        "no_blanket_regime_correction": true
      },
      "chapter_rationale": "Xi scores strongly because the dossier shows a ruler who turned political dominance into concrete governing machinery. He rewrote the elite team, re-centered the congress around his authority, pushed implementation notices, and used inspections and corrections to keep the system moving. The evidence also shows real policy follow-through on economic stabilization, industrial priorities, and late-year pandemic reversal. This is more than symbolic control: it is a full chain from program to enforcement to partial correction. I do not give a higher score because some major outcomes were reactive rather than preventive, and several favorable figures are inputs or policy moves rather than independently verified durable gains. Moral approval of the program did not matter here.",
      "lower_anchor_rejected": "A lower score would miss the degree of elite control, administrative dispatch, and adaptive correction actually visible in the 2022 record.",
      "higher_anchor_rejected": "A higher score is blocked by the fact that important successes are mixed with reactive crisis management and by the absence of equally strong evidence of durable outcome conversion across all major priorities.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "program_basis",
          "value": "explicit"
        },
        {
          "field": "program_type",
          "value": "regime_control; state_building; policy; international_influence"
        },
        {
          "field": "strategic_clarity",
          "value": "exceptional"
        },
        {
          "field": "operationalization",
          "value": "strong"
        },
        {
          "field": "mobilization_and_coordination",
          "value": "strong"
        },
        {
          "field": "adaptation",
          "value": "effective"
        },
        {
          "field": "goal_progress",
          "value": "substantial"
        },
        {
          "field": "durability",
          "value": "durable"
        },
        {
          "field": "morality_separation_check",
          "value": "The score reflects program execution only; the political character of the program did not change the competence judgment."
        },
        {
          "field": "trajectory",
          "value": "strong consolidation with reactive correction under pressure"
        },
        {
          "field": "lens_strengths",
          "value": "8B.1, 8B.2, 8B.3, 8B.5, 8B.6, 8B.9, 8B.10"
        },
        {
          "field": "lens_gaps",
          "value": "Outcome conversion is less clean than elite control and administrative direction."
        },
        {
          "field": "defensible_score_range",
          "value": "7.0-8.5"
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:COD:16113",
