      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E077",
          "explanation": "Tshisekedi personally chaired a major development-program evaluation meeting, indicating real executive attention and oversight."
        },
        {
          "evidence_id": "E080",
          "explanation": "The IMF said macroeconomic conditions improved and prudence increased, which is an actual policy-performance signal."
        },
        {
          "evidence_id": "E083",
          "explanation": "The EITI validation records tangible reforms with presidency-driven impetus, showing some implementation capacity."
        },
        {
          "evidence_id": "E084",
          "explanation": "The appointment and lack of inquiry around the Buhene episode show direct exercise of authority, even if the episode is a negative one."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E085",
          "explanation": "Corruption allegations around close associates show weak network discipline and only partial presidential response."
        },
        {
          "evidence_id": "E082",
          "explanation": "The mining audit found severe irregularities in a state asset, which tempers claims of clean governance."
        },
        {
          "evidence_id": "E081",
          "explanation": "The World Bank notes poverty reduction remained elusive, so growth did not translate cleanly into broad welfare progress."
        }
      ],
